// Sheet columns: A=Keyword, B=Search Volume, C=Competition, D=Blog Post Topic, E=Category, F=Stage, G=Status, H=Notes, I=Featured
const COL = { Keyword:'A', Topic:'D', Category:'E', Stage:'F', Status:'G', Notes:'H', Featured:'I' };
function norm(s){ return String(s).toLowerCase().replace(/[\s_-]+/g,''); }
function getVal(item, names, colLetter){
  const json = item.json || {};
  for (const key of Object.keys(json)){
    for (const name of names){ if (norm(key) === norm(name)) return json[key]; }
  }
  if (colLetter && json[colLetter] !== undefined) return json[colLetter];
  const idx = colLetter ? colLetter.charCodeAt(0) - 65 : -1;
  if (idx >= 0 && json[idx] !== undefined) return json[idx];
  return undefined;
}

if (items.length > 0) console.log('Filter fields: ' + JSON.stringify(Object.keys(items[0].json || {})));

const ready = [];
for (const item of items) {
  const status = String(getVal(item, ['Status'], COL.Status) || '').trim().toLowerCase();
  if (status !== 'ready to write' && status !== 'ready') continue;
  const topic = getVal(item, ['Blog Post Topic (Pinterest Format)','Blog Post Topic','Topic'], COL.Topic);
  const category = getVal(item, ['Category'], COL.Category);
  const keyword = getVal(item, ['Keyword','Focus Keyword'], COL.Keyword);
  if (!topic || !category || !keyword) { console.warn('Skip ready row missing Topic/Category/Keyword'); continue; }
  const rawIdx = item.index;
  ready.push({ item, rowIndex: (rawIdx !== undefined && rawIdx !== null) ? rawIdx : 0 });
}

console.log('Ready topics: ' + ready.length + ' of ' + items.length);
if (ready.length === 0) return [];
ready.sort((a,b) => a.rowIndex - b.rowIndex);
console.log('Processing top ready row index: ' + ready[0].rowIndex);
return [ready[0].item];

const COL = { Keyword:'A', Topic:'D', Category:'E', Stage:'F', Status:'G', Notes:'H', Featured:'I' };
function norm(s){ return String(s).toLowerCase().replace(/[\s_-]+/g,''); }
function getVal(item, names, colLetter){
  const json = item.json || {};
  for (const key of Object.keys(json)){
    for (const name of names){ if (norm(key) === norm(name)) return json[key]; }
  }
  if (colLetter && json[colLetter] !== undefined) return json[colLetter];
  const idx = colLetter ? colLetter.charCodeAt(0) - 65 : -1;
  if (idx >= 0 && json[idx] !== undefined) return json[idx];
  return undefined;
}

const first = items[0];
const rawIdx = first.index;

const categoryMap = {
  'intentional parenting': 'intentional-parenting',
  'intentional parenting & discipline': 'intentional-parenting',
  'real talk': 'real-talk',
  'real talk / unfiltered motherhood': 'real-talk',
  'toddler': 'toddler',
  'toddler & early childhood': 'toddler',
  'family routines': 'family-routines',
  'family routines & rhythms': 'family-routines',
  'printables': 'printables',
  'printables & family tools': 'printables'
};

const topicRaw = getVal(first, ['Blog Post Topic (Pinterest Format)','Blog Post Topic','Topic'], COL.Topic);
const categoryRaw = getVal(first, ['Category'], COL.Category);
const keywordRaw = getVal(first, ['Keyword','Focus Keyword'], COL.Keyword);
const stageRaw = getVal(first, ['Stage'], COL.Stage);
const notesRaw = getVal(first, ['Notes','Context'], COL.Notes);
const featuredRaw = getVal(first, ['Featured'], COL.Featured);

const normalizedCategory = categoryMap[String(categoryRaw || '').toLowerCase()]
  || String(categoryRaw || '').toLowerCase().replace(/\s+/g, '-');

const slug = String(topicRaw || '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '')
  .substring(0, 80);

const stageMap = {
  'intentional-parenting': ['newborn','baby','toddler','preschooler'],
  'real-talk': ['newborn','baby','toddler','preschooler'],
  'toddler': ['toddler','preschooler'],
  'family-routines': ['baby','toddler','preschooler'],
  'printables': ['toddler','preschooler']
};
const stage = (stageRaw && String(stageRaw).trim()) || (stageMap[normalizedCategory] || ['toddler'])[0];

const now = new Date();
const date = now.toISOString().split('T')[0];
const rowIndex = (rawIdx !== undefined && rawIdx !== null) ? rawIdx : 0;

console.log('Preparing: ' + topicRaw + ' -> ' + slug);

return [{
  json: {
    rowIndex,
    topic: String(topicRaw || '').trim(),
    titleHint: String(topicRaw || '').trim(),
    category: String(categoryRaw || '').trim(),
    normalizedCategory,
    focusKeyword: String(keywordRaw || '').trim(),
    stage,
    slug,
    date,
    updated: date,
    additionalContext: notesRaw ? String(notesRaw).trim() : '',
    notes: notesRaw ? String(notesRaw).trim() : '',
    featured: featuredRaw ? String(featuredRaw).toLowerCase() === 'true' : false
  }
}];

// Input: merged payload from Prepare Input meta + Claude response. No node-name references used.
function extractJsonText(s){
  let t = String(s || '').trim().replace(/^```(json)?/i,'').replace(/```$/,'').trim();
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if(start >= 0 && end > start) t = t.slice(start, end + 1);
  return t;
}
function repairJson(s){
  var BS = String.fromCharCode(92);
  let out = '';
  let inStr = false;
  let escaped = false;
  for(let i = 0; i < s.length; i++){
    const ch = s[i];
    if(inStr){
      if(escaped){ if(('"' + BS + BS + '/bfnrtu').indexOf(ch) >= 0){ out += BS + ch; } else { out += ch; } escaped = false; continue; }
      if(ch === BS){ escaped = true; continue; }
      if(ch === '\n'){ out += '\\n'; continue; }
      if(ch === '\r'){ out += '\\r'; continue; }
      if(ch === '\t'){ out += '\\t'; continue; }
      if(ch === '"'){
        let j = i + 1;
        while(j < s.length && /\s/.test(s[j])) j++;
        const nx = s[j] || '';
        if(nx === '' || nx === ':' || nx === ',' || nx === '}' || nx === ']'){ inStr = false; out += ch; continue; }
        out += '\\"'; continue;
      }
      out += ch;
    } else {
      out += ch;
      if(ch === '"') inStr = true;
    }
  }
  return out;
}
let content;
try {
  const blocks = items[0].json.content || [];
  const textBlock = blocks.find(b => b.type === 'text');
  const text = textBlock ? textBlock.text : undefined;
  try {
    content = JSON.parse(text);
  } catch(e1) {
    console.warn('First JSON parse failed, attempting repair: ' + e1.message);
    content = JSON.parse(repairJson(extractJsonText(text)));
    console.warn('Repaired malformed JSON from Claude');
  }
} catch (e) {
  throw new Error('Claude did not return valid JSON: ' + e.message);
}

// Self-heal AI style misses instead of failing the whole run
const stripEmDash = s => String(s || '').replace(/\u2014/g, ' - ');
let emDashFound = false;
for (const k of ['title','description','excerpt']) {
  if (String(content[k] || '').includes('\u2014')) { emDashFound = true; content[k] = stripEmDash(content[k]); }
}
if (content.bodyMarkdown && String(content.bodyMarkdown).includes('\u2014')) { emDashFound = true; content.bodyMarkdown = stripEmDash(content.bodyMarkdown); }
if (emDashFound) console.warn('Removed em dash(es) from output');

let description = String(content.description || '').trim();
let metaWords = description.split(/\s+/).filter(Boolean).length;
if (metaWords > 20) {
  description = description.split(/\s+/).slice(0, 20).join(' ').replace(/[,;:.\-]+$/, '') + '.';
  metaWords = description.split(/\s+/).filter(Boolean).length;
  console.warn('Trimmed meta description to ' + metaWords + ' words');
}
if (metaWords < 17 || metaWords > 20) console.warn('Meta description off target (17-20 words): got ' + metaWords);
content.description = description;

const meta = items[0].json;
const fk = String(meta.focusKeyword || '').toLowerCase();
if (fk && !String(content.title || '').toLowerCase().includes(fk)) console.warn('Title may not contain focus keyword: ' + fk);
const frontmatter = {
  title: content.title,
  description: content.description,
  featuredImage: '/images/posts/' + meta.slug + '.webp',
  category: meta.normalizedCategory,
  stage: meta.stage,
  date: meta.date,
  updated: meta.updated,
  excerpt: content.excerpt,
  keywords: content.keywords,
  featured: meta.featured || content.featured || false
};
const DOWNLOAD_FILES = {
  'chore-chart': '/downloads/chore-chart-printable.pdf',
  'feelings-chart': '/downloads/feelings-chart-printable.pdf',
  'routine-cards': '/downloads/daily-routine-cards.pdf',
  'checklist': '/downloads/printable-checklist.pdf',
  'bedtime-chart': '/downloads/bedtime-routine-chart.pdf',
  'meal-planner': '/downloads/meal-planner.pdf',
  'potty-chart': '/downloads/potty-training-chart.pdf',
  'screen-time-tracker': '/downloads/screen-time-tracker.pdf',
  'family-rules': '/downloads/family-rules-chart.pdf',
  'screen-time-contract': '/downloads/screen-time-agreement.pdf'
};
const downloadHref = DOWNLOAD_FILES[content.downloadType] || null;
if (downloadHref) {
  frontmatter.download = downloadHref;
  frontmatter.downloadTitle = content.downloadIdea || 'Free printable';
} else if (content.downloadType) {
  console.warn('Unknown downloadType, no file linked: ' + content.downloadType);
}
let bodyMd = content.bodyMarkdown;

const lines = Object.entries(frontmatter)
  .filter(([,v]) => v !== undefined && v !== null)
  .map(([k,v]) => {
    if (Array.isArray(v)) return k + ': [' + v.map(x => '"' + String(x).replace(/"/g,'\\"') + '"').join(', ') + ']';
    if (typeof v === 'string') return k + ': "' + v.replace(/"/g,'\\"') + '"';
    return k + ': ' + v;
  });

const fullMdx = '---\n' + lines.join('\n') + '\n---\n\n' + bodyMd;

return [{
  json: {
    rowIndex: meta.rowIndex,
    notes: meta.notes,
    keyword: meta.focusKeyword,
    slug: meta.slug,
    title: content.title,
    description: content.description,
    excerpt: content.excerpt,
    keywords: content.keywords,
    downloadIdea: content.downloadIdea || null,
    featured: meta.featured || content.featured || false,
    metaWordCount: metaWords,
    fullMdx,
    mdxBase64: Buffer.from(fullMdx, 'utf8').toString('base64')
  }
}];

// Final step: mark the row Done in the sheet. Images are pre-uploaded manually to GitHub.
const content = items[0].json;
return [{
  json: {
    rowIndex: content.rowIndex,
    keyword: content.keyword,
    status: 'Done',
    notes: content.notes || '',
    featured: content.featured ? 'TRUE' : 'FALSE',
    slug: content.slug,
    imageUrl: content.coverImageUrl || '/images/posts/' + content.slug + '.webp',
    title: content.title,
    description: content.description,
    generatedAt: new Date().toISOString()
  }
}];
